public System.String GetHashString()
{
    if (pricingAttribute is GUPPricingAttributeEcoResAttribute)
    {
        return (pricingAttribute as GUPPricingAttributeEcoResAttribute).getAttributeKey();
    }
    return int2Str(classIdGet(this.pricingAttribute));
